mapper.select:
SELECT id, user_id, task_name, task_type, cron_expression, description, status,
       last_execute_time, next_execute_time, last_execute_status, execute_count,
       params, remark, create_time, update_time
FROM sys_scheduled_task

    del_flag = 0

        AND user_id = #{userId}


        AND task_name LIKE CONCAT('%', #{taskName}, '%')


        AND task_type = #{taskType}


        AND status = #{status}


ORDER BY create_time DESC
